import cv2 as cv
import cv2
import numpy as np
from matplotlib.pyplot import imshow

# Copie paths of Images
paths =  [r"C:\Users\teddy\OneDrive\Desktop\one_piece_1.2.png"  , r"C:\Users\teddy\OneDrive\Desktop\one_piece.png" , r"C:\Users\teddy\OneDrive\Desktop\one_piece_1.2.png" ,  r"C:\Users\teddy\OneDrive\Desktop\one_piece.png" ]
i=0
e1 = cv.getTickCount()
while i < len(paths) :
    img = cv.imread(f"{paths[i]}")
    if  i > 0 :
        img_prev = cv.imread(f"{paths[i-1]}")
    if img is None:
        print("Error")
        break
    weight1 = 1
    weight2 = 0
    while True:
        if i > 0:
            img_2 = cv.addWeighted(img_prev , weight1 , img , weight2 ,0)
            cv.imshow("first" , img_2)
            weight1-= 0.002
            weight2 += 0.002
            cv.waitKey(1)
            if    -0.01 <= weight1 <=0.010000001 :
                    break
        else:
            cv.imshow("first", img)
            break
    cv.waitKey(1000)
    i+=1
e2=cv.getTickCount()
time = (e2-e1) / cv.getTickFrequency()
print(time)